template <bool B>
inline bool VerifyRecordTypeVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<RecordType> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyRecordType(
        verifier,  values->Get(i), types->GetEnum<RecordType>(i))) {
      return false;
    }
  }
  return true;
}

